    @Override
    public void act(List<Entity> newLions, Weather weather, TimeOfDay time) {
        incrementAge();
        incrementHunger();
        if(isAlive()) {

            giveBirth(newLions);

            if (time == TimeOfDay.NIGHT){
                return;
