                //eatOrLeave(prey);
                if (plant.isAlive()) {
                    //System.out.println("ALIVE");
                    plant.setDead();
                    // NOTE: ONLY RETURN WHERE IF EATEN
                    boolean eaten = eat(plant);

                    //return where;
                    return eaten ? where : null;
                }
            }
        }
        return null;
    }
